import os,re,json
d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n')
G={}
for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
    k,h,w=m[1],int(m[2]),int(m[3])
    rows=[r.split() for r in t[m.end():].split('\n')[:h]]
    if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
        G[k]=[[int(x) for x in r] for r in rows]
print(sorted(G))

def solve_diag(inp,out):
    H,W=len(inp),len(inp[0])
    # diagonal lines: constant j-i
    lines={}
    for i in range(H):
        for j in range(W):
            c=inp[i][j]
            if c: lines.setdefault(j-i,set()).add(c)
    # also check horizontal hypothesis
    hlines={}
    for i,row in enumerate(inp):
        cs=set(x for x in row if x)
        if len(cs)==1 and all(x==list(cs)[0] for x in row if x): hlines[i]=cs.pop()
    p=len(lines)
    pat={k%p:list(v)[0] for k,v in lines.items()}
    print('diag lines',lines,'p',p,'pat',pat)
    pred=[[pat[(j-i)%p] for j in range(W)] for i in range(H)]
    return pred==out

print('demo2 match:', solve_diag(G['Demo pair 2 input'],G['Demo pair 2 output']))
